@RabbitListener(queues = "primary.queue")
public class OrderConsumer {

    private static final Logger log = LoggerFactory.getLogger(OrderConsumer.class);

    @Autowired
    private OrderProcessingService orderService;

    @RabbitHandler
    public void handleOrder(OrderPayload payload, Channel channel, @Header(AmqpHeaders.DELIVERY_TAG) long deliveryTag) throws IOException {
        try {
            orderService.process(payload);
            channel.basicAck(deliveryTag, false);
        \} catch (TransientDatabaseException e) {
            log.warn("Transient failure processing order {}. Requeuing for retry.", payload.getOrderId(), e);
            // Requeue=false routes the message to the configured Dead Letter Exchange (DLX)
            channel.basicNack(deliveryTag, false, false);
        \} catch (Exception e) {
            log.error("Permanent failure processing order {}. Dropping to DLQ.", payload.getOrderId(), e);
            channel.basicReject(deliveryTag, false);
        }
    }
}
